const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Define geometry for Banamepe area along Digul River, Papua, Indonesia
  const banamepe = ee.Geometry.Point([139.3, -5.5]);
  const studyArea = banamepe.buffer(5000); // 5km radius buffer

  console.log("Analyzing forest cover change near Banamepe, Digul River");
  console.log("Study area: 5km radius buffer");

  // 2. Load Hansen Global Forest Change dataset
  const hansen = ee.Image('UMD/hansen/global_forest_change_2023_v1_11');

  // 3. Extract relevant bands
  const treecover2000 = hansen.select('treecover2000'); // Tree cover in year 2000 (%)
  const lossYear = hansen.select('lossyear'); // Year of forest loss (0-23 for 2000-2023)

  // 4. Calculate forest cover in 2002 (baseline)
  // Assume minimal loss between 2000-2002, use 2000 as baseline
  const forestMask2000 = treecover2000.gte(30); // >= 30% tree cover threshold

  const forest2002Area = forestMask2000.multiply(ee.Image.pixelArea());
  const forest2002Stats = forest2002Area.reduceRegion({
    reducer: ee.Reducer.sum(),
    geometry: studyArea,
    scale: 30,
    maxPixels: 1e9
  });

  const forest2002 = forest2002Stats.get('treecover2000').getInfo();

  // Check for valid data
  if (forest2002 === null || forest2002 === undefined) {
    console.log("No forest data available for this location");
    console.log("<answer>C1</answer>");
    return;
  }

  // 5. Calculate forest loss from 2000 to 2019
  // lossYear band: values 1-23 represent years 2001-2023
  // For losses through 2019, we need lossYear <= 19
  const lossThrough2019 = lossYear.gte(1).and(lossYear.lte(19));
  const lostForest = forestMask2000.and(lossThrough2019);

  const lostArea = lostForest.multiply(ee.Image.pixelArea());
  const lossStats = lostArea.reduceRegion({
    reducer: ee.Reducer.sum(),
    geometry: studyArea,
    scale: 30,
    maxPixels: 1e9
  });

  const lostForestArea = lossStats.get('lossyear').getInfo();

  // 6. Calculate remaining forest in 2019
  const forest2019 = forest2002 - (lostForestArea || 0);

  // 7. Count valid pixels
  const pixelCount = forestMask2000.reduceRegion({
    reducer: ee.Reducer.count(),
    geometry: studyArea,
    scale: 30,
    maxPixels: 1e9
  }).get('treecover2000').getInfo();

  if (pixelCount === 0) {
    console.log("No valid pixels in study area");
    console.log("<answer>C2</answer>");
    return;
  }

  // 8. Print results
  const forest2002Ha = (forest2002 / 10000).toFixed(2);
  const forest2019Ha = (forest2019 / 10000).toFixed(2);
  const lossHa = ((lostForestArea || 0) / 10000).toFixed(2);
  const lossPercent = ((lostForestArea || 0) / forest2002 * 100).toFixed(1);

  console.log(`Forest 2002: ${forest2002Ha} ha`);
  console.log(`Forest loss 2002-2019: ${lossHa} ha`);
  console.log(`Forest 2019: ${forest2019Ha} ha`);
  console.log(`Loss percentage: ${lossPercent}%`);
  console.log(`Valid pixels: ${pixelCount}`);

  // 9. Determine answer
  if (forest2002 === null || forest2019 === null || isNaN(forest2002) || isNaN(forest2019)) {
    console.log("Calculation returned invalid values");
    console.log("<answer>C3</answer>");
  } else if (lostForestArea > 0 && forest2019 < forest2002) {
    console.log("Forest cover decreased");
    console.log("<answer>A</answer>");
  } else {
    console.log("No significant forest decrease detected");
    console.log("<answer>B</answer>");
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
